mapper.select:


    sl.deleted = 0

        and sl.schedule_resource_id = #{scheduleResourceId}


        and sl.schedule_id = #{scheduleId}


        and sl.resource_id = #{resourceId}


        and sl.event_id = #{eventId}


        and sl.slot_status = #{slotStatus}


        and sl.start_time >= #{startTime}


        and sl.end_time <= #{endTime}


order by sl.start_time asc, sl.slot_id asc

select count(1)
from competition_scene_resource_slot
where deleted = 0
  and schedule_resource_id = #{scheduleResourceId}
  and start_time < #{endTime}
  and end_time > #{startTime}

  and slot_id != #{excludeSlotId}
